#include <stdio.h>

enum Status { STATUS_NEW = 2, STATUS_RUNNING, STATUS_DONE = 8, STATUS_FAILED };

int main(void)
{
    printf("%d %d %d %d\n", STATUS_NEW, STATUS_RUNNING, STATUS_DONE, STATUS_FAILED);
    return 0;
}

#include <stdio.h>

enum Status { STATUS_NEW = 2, STATUS_RUNNING, STATUS_DONE = 8, STATUS_FAILED };

int main(void)
{
    enum Status status = STATUS_DONE;
    switch (status) {
        case STATUS_NEW: puts("new"); break;
        case STATUS_RUNNING: puts("running"); break;
        case STATUS_DONE: puts("done"); break;
        case STATUS_FAILED: puts("failed"); break;
        default: puts("unknown"); break;
    }
    return 0;
}

#include <stdio.h>

enum Stage { STAGE_DRAFT, STAGE_REVIEW, STAGE_PUBLISHED };

int main(void)
{
    enum Stage stage = STAGE_DRAFT;
    stage = STAGE_REVIEW;
    printf("%d %d\n", stage == STAGE_REVIEW, STAGE_PUBLISHED);
    return 0;
}

